console.log('Webhook input received:', $json);
const data = $json.body || {};
console.log('Form data departureLocation:', data.departureLocation);
console.log('Form data customAirport:', data.customAirport);

return [{
  json: {
    departureLocation: data.customAirport || data.departureLocation || "Not provided",
    destination: data.customDestination || data.destination || "Not specified",
    budget: data.budget || "~",
    tripType: data.tripType || "N/A",
    groupSize: data.groupSize || "1",
    ageRange: Array.isArray(data.ageRange) ? data.ageRange : (data.ageRange ? [data.ageRange] : ["~"]),
    dayActivity: Array.isArray(data.dayActivity) ? data.dayActivity.join(", ") : (data.dayActivity || "none"),
    nightActivity: Array.isArray(data.nightActivity) ? data.nightActivity.join(", ") : (data.nightActivity || "none"),
    startDate: data.startDate || "N/A",
    endDate: data.endDate || "N/A",
    email: data.email || "unknown"
  }
}];

console.log('Processing in Travel Info node');
const travel = $node["Code"].json;
console.log('Travel Info departureLocation:', travel.departureLocation);

// Calculate the number of days between startDate and endDate
const startDate = new Date(travel.startDate);
const endDate = new Date(travel.endDate);
const timeDiff = endDate - startDate;
const days = Math.ceil(timeDiff / (1000 * 60 * 60 * 24)) + 1; // Include both start and end days

// Generate daily activities for Turks & Caicos
let dailyActivities = '';

// Day 1: Arrival and light activities
dailyActivities += `### Day 1: Arrival in Turks & Caicos (July 1)\n` +
  `- **Morning**: Flight from ${travel.departureLocation} to Providenciales (PLS).\n` +
  `- **Afternoon**: Check into your hotel near Grace Bay Beach.\n` +
  `- **Evening**: Dinner at a local restaurant like Coco Bistro. 🍽️ [Reservation](https://cocobistro.tc/)\n\n`;

// Day 2: Beach Relaxation
dailyActivities += `### Day 2: Beach Relaxation (July 2)\n` +
  `- **Morning**: Relax at Grace Bay Beach, one of the world's best beaches. 🌊\n` +
  `- **Afternoon**: Lunch at Somewhere Café and Lounge. 🍽️ [Menu](https://somewherecafeandlounge.com/)\n` +
  `- **Evening**: Enjoy nightlife at Danny Buoy's. 🎶 [Info](https://www.dannybuoys.com/)\n\n`;

// Day 3: Snorkeling Adventure
dailyActivities += `### Day 3: Snorkeling Adventure (July 3)\n` +
  `- **Morning**: Book a snorkeling tour to the Turks & Caicos Barrier Reef. 🏄‍♂️ [Tour Info](https://www.dive.tc/)\n` +
  `- **Afternoon**: Continue relaxing at Grace Bay Beach.\n` +
  `- **Evening**: Attend a local music event in Providenciales. 🎶\n\n`;

// Day 4: Island Excursion
dailyActivities += `### Day 4: Island Excursion (July 4)\n` +
  `- **Morning**: Take an island-hopping excursion to North Caicos and Middle Caicos. 🚤 [Tour Info](https://www.turksandcaicostourism.com/island-hopping/)\n` +
  `- **Afternoon**: Visit Mudjin Harbour for stunning views.\n` +
  `- **Evening**: Beach bonfire at your hotel. 🔥\n\n`;

// Day 5: Adventure Sports
dailyActivities += `### Day 5: Adventure Sports (July 5)\n` +
  `- **Morning**: Go kiteboarding or paddleboarding at Long Bay Beach. 🪂 [Booking](https://www.kiteprovo.com/)\n` +
  `- **Afternoon**: Relax at Sapodilla Bay, a quieter beach spot.\n` +
  `- **Evening**: Fine dining at Infiniti Restaurant. 🍽️ [Reservation](https://infinitirestaurant.com/)\n\n`;

// Day 6: Departure
dailyActivities += `### Day 6: Departure (July 6)\n` +
  `- **Morning**: Spend your final morning relaxing at Grace Bay Beach. 🌊\n` +
  `- **Afternoon**: Check out of your hotel and catch your flight back to ${travel.departureLocation}.\n`;

// Generate the itinerary in the requested format
let itinerary = `🌍 Trip Plan: ${travel.destination}\n` +
  `(${travel.startDate} to ${travel.endDate})\n` +
  `📍 Departure Location: ${travel.departureLocation}\n\n` +
  `💸 Budget: $${travel.budget} (for ${travel.groupSize} people)\n\n` +
  `✈️ Flights\n` +
  `**Departure City:** ${travel.departureLocation}\n` +
  `**Airlines:** Delta, American Airlines, Air France\n` +
  `**Estimated Cost:** ~ depends on location\n` +
  `**Tips:** Book 3-4 months early, check direct or 1-stop flights\n\n` +
  `🏨 Accommodation\n` +
  `**Example:** Hotel near Grace Bay Beach\n` +
  `**Cost:** $200–$400 per night\n` +
  `**Tip:** Consider boutique hotels or resorts for a luxurious experience\n` +
  `[Book Hotels](https://www.booking.com/searchresults.html?dest_id=-2621515&dest_type=city)\n\n` +
  `📆 Daily Activities\n` +
  `${dailyActivities}\n\n` +
  `🍽️ Food Budget\n` +
  `Estimate $50–$70/day per person for meals. Explore local eateries and markets.\n\n` +
  `📊 Estimated Cost Summary\n` +
  `**Category** | **Cost**\n` +
  `Flights | ~\n` +
  `Accommodation | ~\n` +
  `Activities | ~\n` +
  `Food | ~\n` +
  `**Total** | ~\n\n` +
  `💡 Travel Tips\n` +
  `- 🚌 Consider renting a car for flexibility\n` +
  `- 🌦️ Pack for warm, sunny weather with occasional rain\n` +
  `- 🗣️ English is widely spoken, but a friendly

 goes a long way\n` +
  `- 🔐 Watch out for common tourist scams\n` +
  `- ✨ Enjoy your personalized adventure!\n\n` +
  `This itinerary was automatically created by your AI Travel Agent powered by ChatGPT\n`;

return [{
  json: {
    destination: travel.destination,
    departureLocation: travel.departureLocation,
    startDate: travel.startDate,
    endDate: travel.endDate,
    groupSize: travel.groupSize,
    budget: travel.budget,
    tripType: travel.tripType,
    ageRange: travel.ageRange,
    dayActivity: travel.dayActivity,
    nightActivity: travel.nightActivity,
    email: travel.email,
    itinerary: itinerary
  }
}];

console.log('Processing in Return HTML node');

const trip = $json;
console.log('Return HTML departureLocation:', trip.departureLocation);

// Generate a unique ID for this itinerary
const itineraryId = Date.now().toString();

// Prepare the itinerary data
const itineraryData = {
  tripTitle: `🌍 Trip Plan: ${trip.destination}`,
  departure: trip.departureLocation,
  dates: `${trip.startDate} to ${trip.endDate}`,
  groupSize: trip.groupSize,
  budget: `$${trip.budget}`,
  tripType: trip.tripType,
  ageRange: Array.isArray(trip.ageRange) ? trip.ageRange.join(", ") : trip.ageRange,
  dayActivity: trip.dayActivity,
  nightActivity: trip.nightActivity,
  email: trip.email,
  itinerary: trip.itinerary
};

// Use a relative path for the redirect
const baseUrl = '/travel'; // Adjusted for /travel subdirectory
const redirectUrl = `${baseUrl}/tropical_trip_itinerary.html?itineraryId=${itineraryId}`;
console.log('Setting redirect URL:', redirectUrl);

return [{
  json: {
    redirectUrl: redirectUrl,
    itineraryId: itineraryId,
    itineraryData: itineraryData
  }
}];

console.log('Processing in Prepare Email Data node');
const itineraryId = $json.query.itineraryId;
const email = $json.query.email;

// Retrieve itinerary data from the query parameters
const itineraryData = {
  destination: $json.query.destination || 'Unknown',
  departure: $json.query.departure || 'Not provided',
  dates: $json.query.dates || 'N/A',
  groupSize: $json.query.groupSize || '1',
  budget: $json.query.budget || '~',
  tripType: $json.query.tripType || 'N/A',
  ageRange: $json.query.ageRange || '~',
  dayActivity: $json.query.dayActivity || 'None',
  nightActivity: $json.query.nightActivity || 'None',
  itinerary: $json.query.itinerary || 'No itinerary found.'
};

const itineraryLink = `/travel/tropical_trip_itinerary.html?itineraryId=${itineraryId}`;

return [{
  json: {
    email: email,
    subject: `Your AI Travel Plan for ${itineraryData.destination}`,
    message: `<div style="font-family: Arial, sans-serif; background-color: #f9f9f9; padding: 20px;">
  <h2 style="color:#2a4a6e;">🌍 Trip Plan: ${itineraryData.destination}</h2>
  <p><strong>Date:</strong> ${itineraryData.dates}</p>
  <p><strong>Departure From:</strong> ${itineraryData.departure}</p>
  <p><strong>Budget:</strong> ${itineraryData.budget} (for ${itineraryData.groupSize} people)</p>
  <p><strong>Trip Type:</strong> ${itineraryData.tripType}</p>
  <p><strong>Age Ranges:</strong> ${itineraryData.ageRange}</p>
  <p><strong>Day Activities:</strong> ${itineraryData.dayActivity}</p>
  <p><strong>Night Activities:</strong> ${itineraryData.nightActivity}</p>
  <p><strong>Access Your Itinerary:</strong> <a href="${itineraryLink}">${itineraryLink}</a></p>
  <hr>
  <pre style="white-space: pre-wrap; font-size: 14px;">${itineraryData.itinerary}</pre>
  <hr>
  <p style="font-size:12px; color:#999;">Generated by Voyage Genie ✨</p>
</div>`
  }
}];
